// The figure gallery is a published surface, so it needs the same coverage check the report library got.
//
// WHAT SLIPPED. The last pass added web/depth-precision-figure.svg, linked it from the public summary, and the link
// worked -- because `web/*.svg` is served directly. It was never listed in web/figures.json, so the gallery a reader
// goes to for "all the figures" was missing a figure the feed had cited. A served file and an inventoried file are
// two different claims, and only the second one is checked here.
//
// The manifest is generated by scripts/p87-figures-manifest.ts from the committed directory, so the fix for a new
// figure is to re-run the generator -- and the fix for forgetting to re-run it is this file.
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { resolve } from "node:path";

const HERE = resolve(process.cwd());
const doc = JSON.parse(readFileSync(resolve(HERE, "web", "figures.json"), "utf8")) as {
  schema: string;
  count: number;
  figures: Array<{ src: string; title: string }>;
};

const servedSvgs = readdirSync(resolve(HERE, "web")).filter((f) => f.endsWith(".svg")).sort();

test("every figure the site serves is inventoried in the gallery", () => {
  const listed = new Set(doc.figures.map((f) => f.src));
  const missing = servedSvgs.filter((f) => !listed.has(f));
  assert.deepEqual(missing, [], `${missing.length} committed SVG(s) are served but not listed -- run npm run p87:figures-manifest`);
});

test("every gallery card points at a file that exists, and no figure is listed twice", () => {
  const seen = new Set<string>();
  for (const f of doc.figures) {
    assert.ok(existsSync(resolve(HERE, "web", f.src)), `${f.src} is in the manifest but not in web/`);
    assert.ok(!seen.has(f.src), `${f.src} appears twice`);
    seen.add(f.src);
    assert.ok(f.title.length > 0 && !/[^\x00-\x7F]/.test(f.title), `${f.src}: a title must exist and be ASCII`);
  }
  assert.equal(doc.count, doc.figures.length, "the declared count must match the list it declares");
});

test("the manifest is derived from the directory, not from a hand-kept list", () => {
  const src = readFileSync(resolve(HERE, "scripts", "p87-figures-manifest.ts"), "utf8");
  assert.match(src, /readdirSync\(WEB_DIR\)|readdirSync\("web"\)|readdirSync\(WEB_DIR/, "the generator must inventory the committed directory");
  assert.match(src, /\.endsWith\(".svg"\)/, "and filter on the extension, so a new figure appears by being added");
  const pkg = JSON.parse(readFileSync(resolve(HERE, "package.json"), "utf8")) as { scripts: Record<string, string> };
  assert.equal(pkg.scripts["p87:figures-manifest"], "tsx scripts/p87-figures-manifest.ts");
});

test("the two figures this audit pass added are actually in the gallery", () => {
  // Named rather than merely counted: "the manifest has 26 entries" stays green while the two nobody looks for
  // are the two that are missing.
  for (const src of ["anchor-counts-figure.svg", "depth-precision-figure.svg"]) {
    assert.ok(doc.figures.some((f) => f.src === src), `${src} must be listed`);
  }
  assert.ok(servedSvgs.includes("anchor-counts-figure.svg"), "and the file it lists must be committed");
});
